    {i : B ⟶ B₁} {j : D ⟶ B₁} {i' : B₁ ⟶ B₂} {j' : D ⟶ B₂}
    (p₀ : IsPushout t s c₀ c₁) (p₁ : IsPushout (t ≫ c₁) s c c₂)
    (p : IsPushout (t ≫ a) s i j) (p' : IsPushout (t ≫ j) s i' j')
    (m : T ⟶ B₂) (hm₀ : (c₀ ≫ c) ≫ m = a ≫ i ≫ i')
